set local role authenticated;
do $$ declare g uuid:=current_setting('qa.civic_game')::uuid;p uuid:=current_setting('qa.civic_party')::uuid;admin uuid:='9fdf732c-1a84-4435-979d-e0272c2b81db';a uuid:='89de1d45-8973-4f38-980d-26042af9e53e';b uuid:='a4795eef-fbf3-4584-bc0b-f7bfee68b783';v uuid;result jsonb;blocked boolean;office uuid;d1 uuid;d2 uuid;c uuid;assignment uuid;step integer;body uuid;begin
 perform public.set_student_mandates(p,jsonb_build_object(a::text,240,b::text,210));
 if (select base_mandates from public.party_member_mandates where party_id=p and user_id=a)<>240 then raise exception 'FAIL custom mandate allocation';end if;
 blocked:=false;begin perform public.set_student_mandates(p,jsonb_build_object(a::text,240.5,b::text,209.5));exception when others then blocked:=true;end;if not blocked then raise exception 'FAIL fractional mandates accepted';end if;
 perform public.apply_party_ghost_loss(p,45);
 if (select effective_mandates from public.party_member_mandates where party_id=p and user_id=a)<>216 or (select effective_mandates from public.party_member_mandates where party_id=p and user_id=b)<>189 then raise exception 'FAIL proportional GV';end if;
 v:=public.create_civic_vote(g,'QA no quorum',null,'mandate','gd','registered_session','fraction',.5,'eligible_majority',.5,true,false,null,'none','none','QA');
 perform set_config('request.jwt.claim.sub',a::text,true);blocked:=false;begin perform public.cast_vote_allocation(v,100,0,0);exception when others then blocked:=true;end;if not blocked then raise exception 'FAIL attendance gate';end if;
 perform public.register_institution_session(g,'gd');perform public.cast_vote_allocation(v,180,20,10);
 perform set_config('request.jwt.claim.sub',admin::text,true);result:=public.close_procedural_vote(v);
 if result->>'result'<>'no_quorum' or (result->>'needed')::numeric<>226 or (result->>'eligible')::numeric<>450 or (result->>'present')::numeric<>216 then raise exception 'FAIL fixed GD quorum: %',result;end if;
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.register_institution_session(g,'gd');
 perform set_config('request.jwt.claim.sub',admin::text,true);v:=public.create_civic_vote(g,'QA split ballots',null,'mandate','gd','registered_session','fraction',.5,'eligible_majority',.5,true,false,null,'none','none','QA');
