 perform public.cast_vote_allocation(v,100,0,0);perform set_config('request.jwt.claim.sub',admin::text,true);result:=public.close_procedural_vote(v);
 if result->>'result'<>'passed' or (result->>'yes')::numeric<>280 or (result->>'no')::numeric<>20 or (result->>'abstain')::numeric<>10 or (result->>'present')::numeric<>405 or (result->>'cast')::numeric<>310 then raise exception 'FAIL split result / registered presence: %',result;end if;
