 perform set_config('request.jwt.claim.sub',admin::text,true);result:=public.close_procedural_vote(v);if result->>'result'<>'passed' or (result->>'eligible')::numeric<>2 or (result->>'needed')::numeric<>1 then raise exception 'FAIL group government denominator: %',result;end if;
 body:=public.create_voting_body(g,'QA other public body',array[a,b],a);
 v:=public.create_civic_vote(g,'QA custom body',null,'member','unit:'||body::text,'registered_session','fraction',.5,'present_majority',.5,true,false,null,'none','none','QA');
